#include <memory>
#include <atomic>
#include <functional>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    auto pointer = std::make_shared<int>(7);
    std::shared_ptr<int> copy;
    copy = pointer;
    assert(*copy == 7);
    assert(std::hash<std::shared_ptr<int>>{}(copy) == std::hash<int *>{}(copy.get()));
    std::atomic<std::shared_ptr<int>> atomic{pointer};
    assert(*atomic.load() == 7);
    std::atomic_store(&copy, std::make_shared<int>(9));
    assert(*std::atomic_load(&copy) == 9);
    std::weak_ptr<int> weak;
    weak = pointer;
    std::atomic<std::weak_ptr<int>> observer{weak};
    assert(*observer.load().lock() == 7);
}
